// Do not hand-edit; change the .py file and build again. Standards codes are checked against data/standards.js.
// Fields: id, std (Alabama code), part (letter), q, a, lvl (1 on-ramp, 2 on level, 3 stretch), choices, also (other right answers), steps (Vault Raid step help).
export default {"cls": "8th","label": "8th Grade","items": [{"id": "8.1-01","std": "8.1","q": "Is √50 rational or irrational?","a": "Irrational","lvl": 1,"choices": ["Rational","Irrational"],"steps": ["Is 50 a perfect square? Check: 7² = 49 and 8² = 64.","The square root of a number that isn't a perfect square never ends or repeats. What kind of number is that?"]},{"id": "8.1-02","std": "8.1","q": "Is 0.125 rational or irrational?","a": "Rational","lvl": 1,"choices": ["Rational","Irrational"],"steps": ["A rational number can be written as a fraction.","0.125 ends. Write it as {125/1000}. Can every ending decimal be a fraction?"]},{"id": "8.1-03","std": "8.1","q": "Is π rational or irrational?","a": "Irrational","lvl": 1,"choices": ["Rational","Irrational"],"steps": ["π = 3.14159… The digits keep going with no pattern.","A decimal that never ends or repeats can't be written as a fraction. What kind of number is that?"]},{"id": "8.1-04","std": "8.1","q": "Is √81 rational or irrational?","a": "Rational (√81 = 9)","lvl": 1,"choices": ["Rational (√81 = 9)","Irrational"],"steps": ["Is 81 a perfect square? What number times itself is 81?","If the square root is a whole number, it can be written as a fraction."]},{"id": "8.1-05","std": "8.1","q": "Does the decimal for {5/8} terminate or repeat?","a": "Terminates (0.625)","lvl": 1,"part": "a","choices": ["Terminates (0.625)","Repeats"],"steps": ["A fraction means divide: 5 ÷ 8.","Keep dividing. Does it end with a remainder of 0, or does a digit keep repeating?"]},{"id": "8.1-06","std": "8.1","q": "Write {4/9} as a decimal.","a": "0.444… (repeating 4)","lvl": 2,"part": "a","also": ["0.4 repeating","0.444..."],"steps": ["A fraction means divide: 4 ÷ 9.","Keep dividing for a few places. What digit keeps coming back?"]},{"id": "8.1-07","std": "8.1","q": "Write 0.777… (7 repeating) as a fraction.","a": "{7/9}","lvl": 2,"part": "b","steps": ["Let x = 0.777… Then 10x = 7.777…","Subtract: 10x − x = 7.777… − 0.777…, so 9x = 7.","Divide both sides by 9."]},{"id": "8.1-08","std": "8.1","q": "Write 0.272727… (27 repeating) as a fraction in simplest form.","a": "{3/11}","lvl": 2,"part": "b","steps": ["Two digits repeat, so multiply by 100. Let x = 0.2727… Then 100x = 27.2727…","Subtract: 100x − x = 27, so 99x = 27.","Divide by 99, then simplify the fraction."]},{"id": "8.1-09","std": "8.1","q": "Write 0.1666… (6 repeating) as a fraction in simplest form.","a": "{1/6}","lvl": 3,"part": "b","steps": ["Let x = 0.1666… Then 10x = 1.666… and 100x = 16.666…","Subtract: 100x − 10x = 16.666… − 1.666…, so 90x = 15.","Divide by 90, then simplify the fraction."]},{"id": "8.1-10","std": "8.1","q": "Write 1.333… (3 repeating) as a fraction.","a": "{4/3}","lvl": 3,"part": "b","also": ["1{1/3}"],"steps": ["Let x = 1.333… Then 10x = 13.333…","Subtract: 10x − x = 12, so 9x = 12.","Divide by 9, then simplify the fraction."]},{"id": "8.1-11","std": "8.1","q": "Which number is irrational? A. −{2/3}  B. 0.5  C. √7  D. √16","a": "C","lvl": 2,"choices": ["A","B","C","D"],"steps": ["Rational numbers are fractions, ending decimals, or repeating decimals.","Check each square root: is 7 a perfect square? Is 16?"]},{"id": "8.2-01","std": "8.2","q": "√30 is between which two whole numbers?","a": "5 and 6","lvl": 1,"also": ["5, 6"],"steps": ["Find the perfect squares on each side of 30: 5² = 25 and 6² = 36.","30 is between 25 and 36, so √30 is between their square roots."]},{"id": "8.2-02","std": "8.2","q": "√70 is between which two whole numbers?","a": "8 and 9","lvl": 1,"also": ["8, 9"],"steps": ["Find the perfect squares on each side of 70: 8² = 64 and 9² = 81.","70 is between 64 and 81, so √70 is between their square roots."]},{"id": "8.2-03","std": "8.2","q": "Is √40 closer to 6 or 7?","a": "6 (40 is closer to 36 than to 49)","lvl": 2,"also": ["6"],"steps": ["6² = 36 and 7² = 49.","Is 40 closer to 36 or to 49? Find each distance."]},{"id": "8.2-04","std": "8.2","q": "Estimate √20 to the nearest tenth.","a": "4.5","lvl": 2,"steps": ["4² = 16 and 5² = 25, so √20 is between 4 and 5.","Try tenths: 4.4² = 19.36 and 4.5² = 20.25.","Which one is closer to 20?"]},{"id": "8.2-05","std": "8.2","q": "Which is greater: √50 or 7.2?","a": "7.2","lvl": 2,"also": ["7.2"],"steps": ["Square both numbers so they're easy to compare: (√50)² = 50.","7.2² = 7.2 × 7.2. Which square is bigger?"]},{"id": "8.2-06","std": "8.2","q": "Order from least to greatest: √10, 3.5, π","a": "π, √10, 3.5","lvl": 3,"steps": ["Change each to a decimal: √10 is a little more than 3, since 3² = 9.","√10 ≈ 3.16, π ≈ 3.14, and 3.5 is 3.5.","Put the decimals in order from smallest to biggest."]},{"id": "8.2-07","std": "8.2","q": "Estimate √2 to the nearest tenth.","a": "1.4","lvl": 2,"steps": ["1² = 1 and 2² = 4, so √2 is between 1 and 2.","Try tenths: 1.4² = 1.96 and 1.5² = 2.25. Which is closer to 2?"]},{"id": "8.2-08","std": "8.2","q": "Between which two consecutive whole numbers is −√12?","a": "−4 and −3","lvl": 3,"also": ["−4, −3"],"steps": ["First find √12: 3² = 9 and 4² = 16, so √12 is between 3 and 4.","−√12 is the opposite, so it's between −4 and −3. Write them in order."]},{"id": "8.2-09","std": "8.2","q": "Estimate π² to the nearest whole number.","a": "10","lvl": 3,"steps": ["π is about 3.14.","π² = π × π. Multiply 3.14 × 3.14, then round to a whole number."]},{"id": "8.3-01","std": "8.3","q": "Simplify: 3² × 3⁴","a": "3⁶","lvl": 1,"also": ["729","3^6"],"steps": ["Same base, multiplying: add the exponents.","Add: 2 + 4. Keep the base 3."]},{"id": "8.3-02","std": "8.3","q": "Simplify: 5⁷ ÷ 5³","a": "5⁴","lvl": 1,"also": ["625","5^4"],"steps": ["Same base, dividing: subtract the exponents.","Subtract: 7 − 3. Keep the base 5."]},{"id": "8.3-03","std": "8.3","q": "Simplify: (2³)²","a": "2⁶","lvl": 1,"also": ["64","2^6"],"steps": ["A power of a power: multiply the exponents.","Multiply: 3 × 2. Keep the base 2."]},{"id": "8.3-04","std": "8.3","q": "Evaluate: 4⁰","a": "1","lvl": 1,"steps": ["Any number (except 0) to the zero power is the same value.","Think: 4³ ÷ 4³ = 4⁰. What is any number divided by itself?"]},{"id": "8.3-05","std": "8.3","q": "Evaluate: 2⁻³","a": "{1/8}","lvl": 2,"steps": ["A negative exponent means one over the positive power: 2⁻³ = {1/2³}.","Find 2³ = 2 × 2 × 2."]},{"id": "8.3-06","std": "8.3","q": "Simplify: x⁵ · x⁻²","a": "x³","lvl": 2,"also": ["x^3"],"steps": ["Same base, multiplying: add the exponents: 5 + (−2).","Keep the base x."]},{"id": "8.3-07","std": "8.3","q": "Simplify: (x⁴)³","a": "x¹²","lvl": 2,"also": ["x^12"],"steps": ["A power of a power: multiply the exponents: 4 × 3.","Keep the base x."]},{"id": "8.3-08","std": "8.3","q": "Evaluate: 3⁻² × 3⁵","a": "27","lvl": 2,"also": ["3³"],"steps": ["Same base, multiplying: add the exponents: −2 + 5.","Then find 3 to that power."]},{"id": "8.3-09","std": "8.3","q": "Simplify and write with a positive exponent: {a³/a⁷}","a": "{1/a⁴}","lvl": 3,"also": ["1/a^4","a^-4"],"steps": ["Same base, dividing: subtract the exponents: 3 − 7.","A negative exponent means one over the positive power."]},{"id": "8.3-10","std": "8.3","q": "Evaluate: (−2)⁴","a": "16","lvl": 2,"steps": ["The −2 is in parentheses, so the negative is multiplied too: (−2)(−2)(−2)(−2).","Count the negatives. An even number of negatives gives a positive."]},{"id": "8.3-11","std": "8.3","q": "Evaluate: −2⁴","a": "−16","lvl": 3,"steps": ["No parentheses: only the 2 is raised to the 4th power. The negative waits.","Find 2⁴ first, then make it negative."]},{"id": "8.3-12","std": "8.3","q": "Simplify: (3x²)³","a": "27x⁶","lvl": 3,"also": ["27x^6"],"steps": ["Raise each part inside to the 3rd power: 3³ and (x²)³.","3³ = 3 × 3 × 3. For (x²)³, multiply the exponents."]},{"id": "8.4-01","std": "8.4","q": "Evaluate: √144","a": "12","lvl": 1,"part": "a","steps": ["What number times itself is 144?","Try 12 × 12."]},{"id": "8.4-02","std": "8.4","q": "Evaluate: ∛125","a": "5","lvl": 1,"part": "a","steps": ["A cube root asks: what number times itself 3 times is 125?","Try 5 × 5 × 5."]},{"id": "8.4-03","std": "8.4","q": "Evaluate: √225","a": "15","lvl": 1,"part": "a","steps": ["What number times itself is 225?","It ends in 5, so try 15 × 15."]},{"id": "8.4-04","std": "8.4","q": "Evaluate: ∛1000","a": "10","lvl": 1,"part": "a","steps": ["What number times itself 3 times is 1000?","Try 10 × 10 × 10."]},{"id": "8.4-05","std": "8.4","q": "Solve: x² = 64","a": "x = ±8","lvl": 2,"also": ["8 and −8","±8"],"steps": ["Take the square root of both sides: x = √64 or x = −√64.","Both a positive and a negative number squared give 64. Write both with ±."]},{"id": "8.4-06","std": "8.4","q": "Solve: x³ = 27","a": "x = 3","lvl": 2,"steps": ["Take the cube root of both sides: x = ∛27.","What number times itself 3 times is 27?"]},{"id": "8.4-07","std": "8.4","q": "Solve: x² = 13","a": "x = ±√13","lvl": 2,"also": ["±√13"],"steps": ["Take the square root of both sides.","13 is not a perfect square, so leave it as a square root. Don't forget ±."]},{"id": "8.4-08","std": "8.4","q": "Solve: x³ = −216","a": "x = −6","lvl": 3,"steps": ["Take the cube root of both sides: x = ∛(−216).","A negative times itself 3 times stays negative. What number cubed is 216?"]},{"id": "8.4-09","std": "8.4","q": "A square has area 81 cm². What is its side length?","a": "9 cm","lvl": 1,"also": ["9"],"steps": ["A square's area is side × side.","What number times itself is 81? Use cm for the unit."]},{"id": "8.4-10","std": "8.4","q": "A cube has volume 343 in³. What is its edge length?","a": "7 in","lvl": 2,"also": ["7"],"steps": ["A cube's volume is edge × edge × edge.","What number times itself 3 times is 343? Use inches."]},{"id": "8.4-11","std": "8.4","q": "Why is √15 irrational?","a": "15 is not a perfect square, so its square root never ends or repeats","lvl": 2,"part": "b","also": ["not a perfect square"],"steps": ["Is 15 a perfect square? 3² = 9 and 4² = 16.","The square root of a number that isn't a perfect square never ends or repeats."]},{"id": "8.4-12","std": "8.4","q": "Solve: 2x² = 50","a": "x = ±5","lvl": 3,"also": ["±5"],"steps": ["Divide both sides by 2 first. Now it's x² = 25.","Take the square root of both sides. Don't forget ±."]},{"id": "8.5-01","std": "8.5","q": "Write 4,500,000 in scientific notation.","a": "4.5 × 10⁶","lvl": 1,"steps": ["Scientific notation is a number from 1 to 10 times a power of 10.","Move the decimal to make 4.5. Count how many places you moved it."]},{"id": "8.5-02","std": "8.5","q": "Write 0.00072 in scientific notation.","a": "7.2 × 10⁻⁴","lvl": 1,"steps": ["Move the decimal right until you get a number from 1 to 10: 7.2.","Count the places you moved. Moving right for a small number makes the exponent negative."]},{"id": "8.5-03","std": "8.5","q": "Write 3.1 × 10⁵ in standard form.","a": "310,000","lvl": 1,"steps": ["10⁵ means move the decimal 5 places to the right.","Start with 3.1 and move the decimal 5 places, adding zeros."]},{"id": "8.5-04","std": "8.5","q": "Which is greater: 6 × 10⁸ or 9 × 10⁷?","a": "6 × 10⁸","lvl": 2,"steps": ["Compare the powers of 10 first: 10⁸ and 10⁷.","The bigger power of 10 is the bigger number, no matter the front number."]},{"id": "8.5-05","std": "8.5","q": "Estimate 49,800,000 as a single digit times a power of 10.","a": "5 × 10⁷","lvl": 2,"steps": ["Round 49,800,000 to one digit: about 50,000,000.","Write 50,000,000 as 5 times a power of 10. Count the zeros."]},{"id": "8.5-06","std": "8.5","q": "The Sun is about 1.5 × 10⁸ km from Earth. The Moon is about 4 × 10⁵ km away. About how many times farther is the Sun?","a": "About 375 times","lvl": 3,"also": ["375"],"steps": ["How many times farther means divide: (1.5 × 10⁸) ÷ (4 × 10⁵).","Divide the front numbers: 1.5 ÷ 4. Subtract the exponents: 8 − 5.","Multiply them together to get a regular number."]},{"id": "8.5-07","std": "8.5","q": "Order from least to greatest: 3 × 10⁻², 5 × 10⁻³, 1 × 10⁻¹","a": "5 × 10⁻³, 3 × 10⁻², 1 × 10⁻¹","lvl": 2,"steps": ["Compare the powers of 10 first: 10⁻³ is the smallest and 10⁻¹ is the biggest.","Write them from the smallest power to the biggest."]},{"id": "8.5-08","std": "8.5","q": "A city has about 8 × 10⁶ people. A town has about 2 × 10⁴. How many times as many people live in the city?","a": "400","lvl": 2,"also": ["4 × 10²"],"steps": ["How many times as many means divide: (8 × 10⁶) ÷ (2 × 10⁴).","Divide the front numbers: 8 ÷ 2. Subtract the exponents: 6 − 4.","Multiply them together to get a regular number."]},{"id": "8.6-01","std": "8.6","q": "Find: (3 × 10⁴)(2 × 10⁵)","a": "6 × 10⁹","lvl": 1,"steps": ["Multiply the front numbers: 3 × 2.","Add the exponents: 10⁴ × 10⁵ = 10⁴⁺⁵."]},{"id": "8.6-02","std": "8.6","q": "Find: (8 × 10⁹) ÷ (2 × 10³)","a": "4 × 10⁶","lvl": 1,"steps": ["Divide the front numbers: 8 ÷ 2.","Subtract the exponents: 9 − 3."]},{"id": "8.6-03","std": "8.6","q": "Find: (5 × 10³)(4 × 10²). Write it in scientific notation.","a": "2 × 10⁶","lvl": 2,"steps": ["Multiply the front numbers: 5 × 4. Add the exponents: 3 + 2.","20 is bigger than 10. Rewrite 20 as 2 × 10¹ and add 1 more to the exponent."]},{"id": "8.6-04","std": "8.6","q": "Find: (6.3 × 10⁵) + (2.1 × 10⁵)","a": "8.4 × 10⁵","lvl": 2,"steps": ["The powers of 10 match, so add the front numbers: 6.3 + 2.1.","Keep × 10⁵."]},{"id": "8.6-05","std": "8.6","q": "Find: (4.5 × 10⁶) − (3 × 10⁵)","a": "4.2 × 10⁶","lvl": 3,"steps": ["Make the powers match first: 3 × 10⁵ = 0.3 × 10⁶.","Now subtract the front numbers: 4.5 − 0.3. Keep × 10⁶."]},{"id": "8.6-06","std": "8.6","q": "Find: 2,000 × (3.5 × 10⁴). Write it in scientific notation.","a": "7 × 10⁷","lvl": 2,"steps": ["Write 2,000 in scientific notation: 2 × 10³.","Multiply the front numbers: 2 × 3.5. Add the exponents: 3 + 4."]},{"id": "8.6-07","std": "8.6","q": "Find: (1.2 × 10⁻³) ÷ (4 × 10²)","a": "3 × 10⁻⁶","lvl": 3,"steps": ["Divide the front numbers: 1.2 ÷ 4.","Subtract the exponents: −3 − 2.","0.3 is less than 1. Rewrite it as 3 × 10⁻¹ and add the exponents."]},{"id": "8.6-08","std": "8.6","q": "A calculator shows 5.6E7. Write it in scientific notation.","a": "5.6 × 10⁷","lvl": 1,"part": "b","steps": ["On a calculator, E means × 10 to that power.","So E7 means × 10⁷."]},{"id": "8.6-09","std": "8.6","q": "A calculator shows 2.3E−4. Write it in standard form.","a": "0.00023","lvl": 2,"part": "b","steps": ["E−4 means × 10⁻⁴: move the decimal 4 places to the left.","Start with 2.3 and move the decimal 4 places left, adding zeros."]},{"id": "8.6-10","std": "8.6","q": "Which unit fits the width of a human hair best (about 8 × 10⁻⁵ m)? Kilometers, meters, or micrometers?","a": "Micrometers","lvl": 2,"part": "a","choices": ["Kilometers","Meters","Micrometers"],"steps": ["8 × 10⁻⁵ m is 0.00008 m. That's tiny.","Which unit is made for tiny lengths: kilometers, meters, or micrometers?"]},{"id": "8.6-11","std": "8.6","q": "Which unit fits the distance between two cities best? Millimeters, centimeters, or kilometers?","a": "Kilometers","lvl": 1,"part": "a","choices": ["Millimeters","Centimeters","Kilometers"],"steps": ["Cities are many miles apart.","Which unit is made for long distances?"]},{"id": "8.7-01","std": "8.7","q": "Is y = 6x proportional?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["Proportional means y = kx: a number times x, with nothing added.","Does y = 6x look like that?"]},{"id": "8.7-02","std": "8.7","q": "Is y = 2x + 5 proportional?","a": "No (it does not pass through the origin)","lvl": 1,"choices": ["Yes","No (it does not pass through the origin)"],"steps": ["Proportional means y = kx with nothing added. Here 5 is added.","Put in x = 0. Does the line go through (0, 0)?"]},{"id": "8.7-03","std": "8.7","q": "x: 2, 4, 6 and y: 7, 14, 21. Proportional or non-proportional?","a": "Proportional (y ÷ x = 3.5)","lvl": 2,"also": ["proportional"],"steps": ["Divide each y by its x: 7 ÷ 2, 14 ÷ 4, 21 ÷ 6.","Proportional means you get the same number every time."]},{"id": "8.7-04","std": "8.7","q": "x: 1, 2, 3 and y: 3, 5, 7. Proportional or non-proportional?","a": "Non-proportional","lvl": 2,"also": ["not proportional","no"],"steps": ["Divide each y by its x: 3 ÷ 1, 5 ÷ 2, 7 ÷ 3.","Proportional means you get the same number every time. Do you?"]},{"id": "8.7-05","std": "8.7","q": "A taxi charges §3 plus §2 a mile. Is the cost proportional to the miles?","a": "No (the §3 start fee)","lvl": 2,"also": ["no"],"steps": ["At 0 miles, what does the ride cost?","Proportional means 0 miles costs §0. Does it?"]},{"id": "8.7-06","std": "8.7","q": "Apples cost §1.50 a pound with no other fees. Is the cost proportional to the pounds?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["Cost = 1.50 × pounds, with no fee added.","At 0 pounds, the cost is §0. Does that fit y = kx?"]},{"id": "8.7-07","std": "8.7","q": "A line passes through (0, 0) and (3, 12). Is it proportional?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["A proportional line goes through (0, 0). This one does.","Check the rate: 12 ÷ 3. Is it a straight line through the origin?"]},{"id": "8.7-08","std": "8.7","q": "A line passes through (0, 4) and (2, 8). Is it proportional?","a": "No","lvl": 1,"choices": ["Yes","No"],"steps": ["A proportional line has to go through (0, 0).","This line goes through (0, 4). Is that the origin?"]},{"id": "8.8-01","std": "8.8","q": "A proportional graph passes through (4, 10). What is the slope?","a": "2{1/2}","lvl": 1,"part": "a","also": ["2.5"],"steps": ["For a proportional graph, slope = y ÷ x.","Divide: 10 ÷ 4. Write it as a mixed number."]},{"id": "8.8-02","std": "8.8","q": "Write the equation of a proportional line through (5, 15).","a": "y = 3x","lvl": 1,"part": "a","steps": ["A proportional line is y = kx, and k = y ÷ x.","Find k: 15 ÷ 5. Then write y = kx."]},{"id": "8.8-03","std": "8.8","q": "A car travels 180 miles in 3 hours at a constant rate. What is the slope of the distance-time graph? What does it mean?","a": "60; the car goes 60 miles per hour","lvl": 2,"part": "a","also": ["60"],"steps": ["Slope = distance ÷ time: 180 ÷ 3.","Say what that number means with units: miles per hour."]},{"id": "8.8-04","std": "8.8","q": "In y = 0.75x, what is the unit rate?","a": "0.75","lvl": 1,"part": "a","steps": ["In y = kx, the unit rate is k, the number in front of x."]},{"id": "8.8-05","std": "8.8","q": "Which point must every proportional graph pass through?","a": "(0, 0)","lvl": 1,"also": ["the origin","origin"],"steps": ["At x = 0, a proportional graph has y = k × 0.","What point is that?"]},{"id": "8.8-06","std": "8.8","q": "A proportional graph of earnings shows (8, 96) for 8 hours. Write the equation.","a": "y = 12x","lvl": 2,"part": "a","steps": ["k = y ÷ x: 96 ÷ 8.","Write it as y = kx."]},{"id": "8.8-07","std": "8.8","q": "Two workers: Ana's graph is y = 14x; Ben earns §45 in 3 hours. Who earns more per hour?","a": "Ben (§15 per hour)","lvl": 3,"part": "a","also": ["Ben"],"steps": ["Ana earns §14 per hour from her equation.","Ben's rate is 45 ÷ 3. Compare the two rates."]},{"id": "8.8-08","std": "8.8","q": "A proportional line passes through (6, 4). Find y when x = 9.","a": "6","lvl": 2,"steps": ["Find k: 4 ÷ 6, which simplifies to {2/3}.","Use y = kx with x = 9: y = {2/3} × 9."]},{"id": "8.9-01","std": "8.9","q": "Find the slope of the line through (1, 2) and (3, 8).","a": "3","lvl": 1,"part": "b","steps": ["Slope = change in y ÷ change in x: {8 − 2/3 − 1}.","Subtract the tops and the bottoms, then divide."]},{"id": "8.9-02","std": "8.9","q": "Find the slope of the line through (−2, 5) and (2, −3).","a": "−2","lvl": 2,"part": "b","steps": ["Slope = change in y ÷ change in x: {−3 − 5/2 − (−2)}.","Top: −3 − 5. Bottom: 2 + 2. Then divide."]},{"id": "8.9-03","std": "8.9","q": "Find the slope of the line through (0, 4) and (6, 7).","a": "{1/2}","lvl": 2,"part": "b","steps": ["Slope = change in y ÷ change in x: {7 − 4/6 − 0}.","Find the top and bottom, then simplify the fraction."]},{"id": "8.9-04","std": "8.9","q": "What are the slope and y-intercept of y = −2x + 7?","a": "Slope −2, y-intercept 7","lvl": 1,"part": "c","also": ["m = −2, b = 7"],"steps": ["In y = mx + b, m is the slope and b is the y-intercept.","Match: m is the number in front of x, and b is the number added."]},{"id": "8.9-05","std": "8.9","q": "A plumber charges §50 to come out plus §40 an hour. Write the cost as y = mx + b.","a": "y = 40x + 50","lvl": 2,"part": "c","steps": ["y = mx + b: m is the cost per hour, and b is the starting fee.","Put in m = 40 and b = 50."]},{"id": "8.9-06","std": "8.9","q": "In y = 40x + 50 (plumber cost), what does 50 mean?","a": "The §50 starting fee (the initial value)","lvl": 2,"part": "c","also": ["50","starting fee"],"steps": ["In y = mx + b, b is what you pay when x = 0.","What do you pay before any hours of work?"]},{"id": "8.9-07","std": "8.9","q": "Write the equation of the line with slope 4 and y-intercept −3.","a": "y = 4x − 3","lvl": 1,"part": "c","steps": ["Use y = mx + b.","Put in m = 4 and b = −3."]},{"id": "8.9-08","std": "8.9","q": "Two slope triangles on the same line have rise/run 2/3 and 6/9. Why are the slopes the same?","a": "The triangles are similar, so 6/9 = 2/3","lvl": 3,"part": "a","also": ["similar triangles"],"steps": ["Simplify {6/9}. What do you get?","The two triangles are the same shape, just different sizes. Same shape on the same line means the same slope."]},{"id": "8.9-09","std": "8.9","q": "Lines y = 3x + 1 and y = 3x − 4 have the same slope. Are they the same line?","a": "No; they are parallel with different y-intercepts","lvl": 2,"part": "d","also": ["no"],"steps": ["Both have slope 3, so they point the same way.","Check the y-intercepts: 1 and −4. Do they cross the y-axis at the same point?"]},{"id": "8.9-10","std": "8.9","q": "Line A goes through (0, 2) and (1, 5). Line B goes through (0, −1) and (2, 5). Do they have the same slope? Do they have the same y-intercept?","a": "Same slope (3), different y-intercepts (2 and −1)","lvl": 3,"part": "d","steps": ["Line A: slope = {5 − 2/1 − 0}. Line B: slope = {5 − (−1)/2 − 0}.","The y-intercept is the y-value at x = 0 for each line.","Compare the slopes, then compare the y-intercepts."]},{"id": "8.9-11","std": "8.9","q": "What is the slope of a horizontal line?","a": "0","lvl": 1,"part": "b","steps": ["A horizontal line is flat: y never changes.","Slope = change in y ÷ change in x. What is the change in y?"]},{"id": "8.10-01","std": "8.10","q": "Plan A: y = 8x. Plan B costs §20 plus §5 per month. Which costs less for 4 months?","a": "Plan A (§32 vs §40)","lvl": 2,"also": ["Plan A","A"],"steps": ["Plan A for 4 months: 8 × 4.","Plan B for 4 months: 20 + 5 × 4.","Compare the two costs."]},{"id": "8.10-02","std": "8.10","q": "Plan A: y = 8x. Plan B: y = 5x + 20. After how many months do they cost the same?","a": "x = 6{2/3} months (about 6.7)","lvl": 3,"also": ["6{2/3}","6{2/3}"],"steps": ["Set the plans equal: 8x = 5x + 20.","Subtract 5x on both sides. Now it's 3x = 20.","Divide both sides by 3. Write it as a mixed number."]},{"id": "8.10-03","std": "8.10","q": "Car A: y = 55x (miles in x hours). Car B travels 240 miles in 4 hours. Which car is faster?","a": "Car B (60 mph)","lvl": 2,"also": ["B","Car B"],"steps": ["Car A goes 55 miles per hour.","Car B's rate: 240 ÷ 4. Compare the speeds."]},{"id": "8.10-04","std": "8.10","q": "Gym A: §30 a month. Gym B: §60 to join plus §20 a month. Which relationship is proportional?","a": "Gym A","lvl": 1,"also": ["A"],"steps": ["Proportional means the cost is §0 for 0 months.","Does either gym charge a fee to join?"]},{"id": "8.10-05","std": "8.10","q": "Gym A: §30 a month. Gym B: §60 to join plus §20 a month. Which costs less for 12 months?","a": "Gym B (§300 vs §360)","lvl": 3,"also": ["B","Gym B"],"steps": ["Gym A for 12 months: 30 × 12.","Gym B for 12 months: 60 + 20 × 12.","Compare the two costs."]},{"id": "8.10-06","std": "8.10","q": "A table shows x: 1, 2, 3 and y: 9, 18, 27. Another relationship is y = 9x + 1. Which is proportional?","a": "The table","lvl": 2,"steps": ["Check the table: divide each y by its x: 9 ÷ 1, 18 ÷ 2, 27 ÷ 3.","Does y = 9x + 1 go through (0, 0)? Put in x = 0."]},{"id": "8.10-07","std": "8.10","q": "Which has the greater rate of change: y = 2.5x + 4 or a line through (0, 0) and (2, 6)?","a": "The line through (0, 0) and (2, 6) (rate 3)","lvl": 2,"also": ["the line","3"],"steps": ["The rate of change of y = 2.5x + 4 is 2.5.","The other line's rate: 6 ÷ 2. Which rate is bigger?"]},{"id": "8.10-08","std": "8.10","q": "Phone plan A: §0.10 per text. Plan B: §5 a month plus §0.05 per text. Which costs less for 200 texts?","a": "Plan B (§15 vs §20)","lvl": 3,"also": ["Plan B","B"],"steps": ["Plan A for 200 texts: 0.10 × 200.","Plan B for 200 texts: 5 + 0.05 × 200.","Compare the two costs."]},{"id": "8.11-01","std": "8.11","q": "Solve: 5x − 3 = 2x + 12","a": "x = 5","lvl": 1,"steps": ["Get the x's on one side: subtract 2x on both sides. Now it's 3x − 3 = 12.","Undo the 3: add 3 on both sides. Now it's 3x = 15.","Divide both sides by 3."]},{"id": "8.11-02","std": "8.11","q": "Solve: 7x + 4 = 3x − 8","a": "x = −3","lvl": 2,"steps": ["Get the x's on one side: subtract 3x on both sides. Now it's 4x + 4 = −8.","Undo the 4: subtract 4 on both sides. Now it's 4x = −12.","Divide both sides by 4."]},{"id": "8.11-03","std": "8.11","q": "Solve: −2x + 9 = 4x − 15","a": "x = 4","lvl": 2,"steps": ["Keep the x's on the side with more: add 2x on both sides. Now it's 9 = 6x − 15.","Undo the 15: add 15 on both sides. Now it's 24 = 6x.","Divide both sides by 6."]},{"id": "8.11-04","std": "8.11","q": "Solve: 3(x + 4) = 27","a": "x = 5","lvl": 1,"steps": ["Divide both sides by 3 first. Now it's x + 4 = 9.","Undo the 4: subtract 4 on both sides."]},{"id": "8.11-05","std": "8.11","q": "Solve: 4(2x − 1) = 3x + 11","a": "x = 3","lvl": 2,"steps": ["Distribute the 4: 8x − 4 = 3x + 11.","Subtract 3x on both sides. Now it's 5x − 4 = 11.","Add 4 on both sides, then divide by 5."]},{"id": "8.11-06","std": "8.11","q": "Solve: 2(x + 5) = 3(x − 1)","a": "x = 13","lvl": 2,"steps": ["Distribute both sides: 2x + 10 = 3x − 3.","Keep the x's on the side with more: subtract 2x on both sides. Now it's 10 = x − 3.","Undo the 3: add 3 on both sides."]},{"id": "8.11-07","std": "8.11","q": "Solve: {2/3}x + 4 = 10","a": "x = 9","lvl": 2,"steps": ["Undo the 4: subtract 4 on both sides. Now it's {2/3}x = 6.","Multiply both sides by {3/2}, the flip of {2/3}."]},{"id": "8.11-08","std": "8.11","q": "Solve: 0.5(x + 6) = 2x − 6","a": "x = 6","lvl": 3,"steps": ["Distribute the 0.5: 0.5x + 3 = 2x − 6.","Subtract 0.5x on both sides. Now it's 3 = 1.5x − 6.","Add 6 on both sides, then divide by 1.5."]},{"id": "8.11-09","std": "8.11","q": "Solve: 7x − 3x + 5 = 21","a": "x = 4","lvl": 1,"steps": ["Combine like terms first: 7x − 3x. Now it's 4x + 5 = 21.","Undo the 5: subtract 5 on both sides, then divide by 4."]},{"id": "8.11-10","std": "8.11","q": "Solve: 4x + 7 = 4x − 2","a": "No solution","lvl": 2,"part": "a","choices": ["One solution","No solution","Infinitely many solutions"],"steps": ["Subtract 4x on both sides. What's left: 7 = −2.","Is 7 = −2 ever true? A statement that's never true means no number works."]},{"id": "8.11-11","std": "8.11","q": "Solve: 2(3x − 1) = 6x − 2","a": "Infinitely many solutions","lvl": 2,"part": "a","choices": ["One solution","No solution","Infinitely many solutions"],"steps": ["Distribute the 2: 6x − 2 = 6x − 2.","Both sides are exactly the same. Is that true for every x?"]},{"id": "8.11-12","std": "8.11","q": "How many solutions does 5x + 2 = 3x + 2 have?","a": "One solution (x = 0)","lvl": 2,"part": "a","choices": ["One solution (x = 0)","No solution","Infinitely many solutions"],"steps": ["Subtract 3x on both sides. Now it's 2x + 2 = 2.","The x's didn't cancel, so there's one answer. Subtract 2, then divide by 2 to find it."]},{"id": "8.11-13","std": "8.11","q": "Gym A: §20 to join plus §15 a month. Gym B: §50 to join plus §10 a month. After how many months is the cost the same?","a": "6 months","lvl": 2,"part": "b","also": ["6"],"steps": ["Write each cost: Gym A is 20 + 15m. Gym B is 50 + 10m.","Set them equal: 20 + 15m = 50 + 10m.","Subtract 10m on both sides, then subtract 20. Now it's 5m = 30. Divide by 5."]},{"id": "8.11-14","std": "8.11","q": "A rectangle's length is 5 more than its width. Its perimeter is 46. Find the length.","a": "14","lvl": 2,"part": "b","steps": ["Let w be the width. The length is w + 5.","Perimeter: 2w + 2(w + 5) = 46. Distribute and combine: 4w + 10 = 46.","Solve for w. The question wants the length, w + 5."]},{"id": "8.11-15","std": "8.11","q": "The sides of a triangle are x, x + 3 and 2x − 1. The perimeter is 30. Find the longest side.","a": "13","lvl": 3,"part": "b","steps": ["Add the sides and set them equal to 30: x + (x + 3) + (2x − 1) = 30.","Combine like terms: 4x + 2 = 30. Solve for x.","Plug x into each side. The question wants the longest one."]},{"id": "8.11-16","std": "8.11","q": "Solve: {x/2} + 3 = {x/5} + 9","a": "x = 20","lvl": 3,"steps": ["Get rid of the fractions: multiply every term by 10, the common denominator.","Now it's 5x + 30 = 2x + 90.","Subtract 2x on both sides, then subtract 30, then divide by 3."]},{"id": "8.12-01","std": "8.12","q": "Solve by substitution: y = 2x and x + y = 12","a": "(4, 8)","lvl": 1,"steps": ["Put 2x in for y in the second equation: x + 2x = 12.","Combine like terms and solve for x.","Put x back into y = 2x to get y. Write it as (x, y)."]},{"id": "8.12-02","std": "8.12","q": "Solve by substitution: y = x + 3 and 2x + y = 18","a": "(5, 8)","lvl": 2,"steps": ["Put x + 3 in for y: 2x + (x + 3) = 18.","Combine like terms: 3x + 3 = 18. Solve for x.","Put x back into y = x + 3. Write it as (x, y)."]},{"id": "8.12-03","std": "8.12","q": "Solve: y = 3x − 5 and y = x + 7","a": "(6, 13)","lvl": 2,"steps": ["Both equal y, so set them equal: 3x − 5 = x + 7.","Subtract x on both sides, then add 5. Now it's 2x = 12. Solve for x.","Put x back into y = x + 7. Write it as (x, y)."]},{"id": "8.12-04","std": "8.12","q": "Solve: y = −x + 4 and y = 2x − 2","a": "(2, 2)","lvl": 2,"steps": ["Both equal y, so set them equal: −x + 4 = 2x − 2.","Add x on both sides, then add 2. Now it's 6 = 3x. Solve for x.","Put x back into y = 2x − 2. Write it as (x, y)."]},{"id": "8.12-05","std": "8.12","q": "Two lines cross at (3, −1). What is the solution to the system?","a": "(3, −1)","lvl": 1,"part": "a","steps": ["The solution to a system is the point where the lines cross.","Write that point as (x, y)."]},{"id": "8.12-06","std": "8.12","q": "Why is the point where two lines cross the solution to the system?","a": "It is on both lines, so it makes both equations true","lvl": 2,"part": "a","steps": ["Every point on a line makes that line's equation true.","The crossing point is on both lines. What does that mean for both equations?"]},{"id": "8.12-07","std": "8.12","q": "How many solutions does y = 2x + 1 and y = 2x − 3 have?","a": "No solution (parallel lines)","lvl": 2,"part": "b","choices": ["One solution","No solution (parallel lines)","Infinitely many solutions"],"steps": ["Both lines have slope 2, but the y-intercepts are 1 and −3.","Same slope with different y-intercepts means parallel lines. Do parallel lines ever cross?"]},{"id": "8.12-08","std": "8.12","q": "How many solutions does y = 3x + 2 and 2y = 6x + 4 have?","a": "Infinitely many solutions (same line)","lvl": 3,"part": "b","choices": ["One solution","No solution","Infinitely many solutions (same line)"],"steps": ["Divide the second equation by 2: y = 3x + 2.","Compare it with the first equation. Same line means every point works."]},{"id": "8.12-09","std": "8.12","q": "Adult tickets are §8 and child tickets are §5. 20 tickets cost §130. How many adult tickets were sold?","a": "10","lvl": 3,"part": "b","steps": ["Let a be adult tickets and c be child tickets: a + c = 20 and 8a + 5c = 130.","From the first: c = 20 − a. Put it in: 8a + 5(20 − a) = 130.","Distribute and combine: 3a + 100 = 130. Solve for a."]},{"id": "8.12-10","std": "8.12","q": "Is (2, 5) a solution to y = 2x + 1 and y = x + 3?","a": "Yes (5 = 5 in both)","lvl": 2,"part": "a","also": ["yes"],"steps": ["Put x = 2 and y = 5 into y = 2x + 1. Is 5 = 2(2) + 1?","Now check y = x + 3. Is 5 = 2 + 3?","It's a solution only if both are true."]},{"id": "8.12-11","std": "8.12","q": "Store A: §10 plus §4 a shirt. Store B: §6 a shirt. When do they cost the same? How many shirts and what cost?","a": "5 shirts, §30","lvl": 3,"part": "b","also": ["(5, 30)"],"steps": ["Store A: 10 + 4s. Store B: 6s. Set them equal: 10 + 4s = 6s.","Subtract 4s on both sides. Now it's 10 = 2s. Solve for s.","Find the cost: put s into 6s."]},{"id": "8.13-01","std": "8.13","q": "Is {(1, 2), (2, 4), (3, 6)} a function?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["A function gives each input exactly one output.","Look at the x-values: 1, 2, 3. Does any x show up twice?"]},{"id": "8.13-02","std": "8.13","q": "Is {(1, 2), (1, 5), (3, 6)} a function?","a": "No (input 1 has two outputs)","lvl": 1,"choices": ["Yes","No (input 1 has two outputs)"],"steps": ["A function gives each input exactly one output.","Look at the x-values. Input 1 shows up twice. Does it have the same output both times?"]},{"id": "8.13-03","std": "8.13","q": "Is {(4, 1), (5, 1), (6, 1)} a function?","a": "Yes (each input has one output)","lvl": 2,"choices": ["Yes (each input has one output)","No"],"steps": ["A function gives each input exactly one output.","The inputs are 4, 5 and 6. Different inputs can share an output. Does any input have two outputs?"]},{"id": "8.13-04","std": "8.13","q": "Does a vertical line pass the vertical line test?","a": "No","lvl": 2,"choices": ["Yes","No"],"steps": ["The test: if any vertical line hits the graph more than once, it's not a function.","A vertical line laid on top of a vertical line touches it at how many points?"]},{"id": "8.13-05","std": "8.13","q": "A table has x: 1, 2, 2, 3 and y: 4, 5, 6, 7. Is it a function?","a": "No (x = 2 has two outputs)","lvl": 1,"also": ["no"],"steps": ["A function gives each input exactly one output.","x = 2 shows up twice. What are its outputs?"]},{"id": "8.13-06","std": "8.13","q": "In a function, each input has exactly ___ output.","a": "One","lvl": 1,"also": ["1"],"steps": ["Think about a vending machine: each button gives you how many snacks?","In a function, each input gets just ___ output."]},{"id": "8.13-07","std": "8.13","q": "A mapping sends 1 → 3, 2 → 3, 3 → 5. Is it a function?","a": "Yes","lvl": 2,"choices": ["Yes","No"],"steps": ["A function gives each input exactly one output.","1 and 2 both go to 3. That's fine. Does any input go to two outputs?"]},{"id": "8.13-08","std": "8.13","q": "Is x = y² (for example (4, 2) and (4, −2)) a function of x?","a": "No","lvl": 3,"choices": ["Yes","No"],"steps": ["Look at the examples: x = 4 gives y = 2 and y = −2.","One input with two outputs. Can that be a function?"]},{"id": "8.14-01","std": "8.14","q": "f(x) = 3x − 4. Find f(5).","a": "11","lvl": 1,"steps": ["Put 5 in for x: f(5) = 3(5) − 4.","Multiply first, then subtract."]},{"id": "8.14-02","std": "8.14","q": "f(x) = −2x + 7. Find f(−3).","a": "13","lvl": 1,"steps": ["Put −3 in for x: f(−3) = −2(−3) + 7.","Negative × negative is positive. Then add 7."]},{"id": "8.14-03","std": "8.14","q": "g(x) = x² + 1. Find g(4).","a": "17","lvl": 2,"steps": ["Put 4 in for x: g(4) = 4² + 1.","Square first, then add 1."]},{"id": "8.14-04","std": "8.14","q": "h(x) = {1/2}x + 6. Find h(10).","a": "11","lvl": 1,"steps": ["Put 10 in for x: h(10) = {1/2}(10) + 6.","Half of 10 first, then add 6."]},{"id": "8.14-05","std": "8.14","q": "f(x) = 5x + 2. Find x when f(x) = 27.","a": "x = 5","lvl": 3,"steps": ["Set the function equal to 27: 5x + 2 = 27.","Subtract 2 on both sides, then divide by 5."]},{"id": "8.14-06","std": "8.14","q": "y = 4x − 1. Find y when x = −2.","a": "−9","lvl": 1,"steps": ["Put −2 in for x: y = 4(−2) − 1.","Multiply first, then subtract 1."]},{"id": "8.14-07","std": "8.14","q": "C(t) = 12t + 15 is the cost of t tickets. Find C(6).","a": "87","lvl": 2,"also": ["§87"],"steps": ["Put 6 in for t: C(6) = 12(6) + 15.","Multiply first, then add 15."]},{"id": "8.14-08","std": "8.14","q": "f(x) = x² − 3x. Find f(−2).","a": "10","lvl": 3,"steps": ["Put −2 in for x: f(−2) = (−2)² − 3(−2).","(−2)² = 4 and −3(−2) = 6.","Combine them: 4 − (−6) means 4 + 6."]},{"id": "8.15-01","std": "8.15","q": "Is y = x² linear or non-linear?","a": "Non-linear","lvl": 1,"part": "a","choices": ["Linear","Non-linear"],"steps": ["A linear function has x to the first power only, like y = mx + b.","Here x is squared. Does it make a straight line?"]},{"id": "8.15-02","std": "8.15","q": "Is y = 4 − 3x linear or non-linear?","a": "Linear","lvl": 1,"part": "a","choices": ["Linear","Non-linear"],"steps": ["Rewrite it: y = −3x + 4.","Does it look like y = mx + b?"]},{"id": "8.15-03","std": "8.15","q": "Table: x 0, 1, 2, 3 and y 1, 2, 4, 8. Linear or non-linear?","a": "Non-linear (y doubles)","lvl": 2,"part": "a","also": ["non-linear","nonlinear"],"steps": ["Find how y changes each time x goes up 1: 1 to 2, 2 to 4, 4 to 8.","Linear means y changes by the same amount every time. Does it?"]},{"id": "8.15-04","std": "8.15","q": "Table: x 0, 1, 2, 3 and y 5, 8, 11, 14. Linear or non-linear?","a": "Linear (adds 3 each time)","lvl": 2,"part": "a","also": ["linear"],"steps": ["Find how y changes each time x goes up 1: 5 to 8, 8 to 11, 11 to 14.","Linear means y changes by the same amount every time. Does it?"]},{"id": "8.15-05","std": "8.15","q": "Function A: y = 3x + 2. Function B goes through (0, 5) and (2, 9). Which has the greater rate of change?","a": "Function A (3 vs 2)","lvl": 2,"also": ["A"],"steps": ["Function A's rate is 3, the number in front of x.","Function B's rate: {9 − 5/2 − 0}. Which rate is bigger?"]},{"id": "8.15-06","std": "8.15","q": "Function A: y = 3x + 2. Function B goes through (0, 5) and (2, 9). Which has the greater y-intercept?","a": "Function B (5 vs 2)","lvl": 2,"also": ["B"],"steps": ["Function A's y-intercept is 2, the number added.","Function B's y-intercept is its y-value when x = 0. Which is bigger?"]},{"id": "8.15-07","std": "8.15","q": "Is y = {6/x} linear?","a": "No","lvl": 2,"part": "a","choices": ["Yes","No"],"steps": ["Here x is on the bottom of the fraction.","Try x = 1, 2, 3: y = 6, 3, 2. Does y change by the same amount each time?"]},{"id": "8.15-08","std": "8.15","q": "Ana saves §10 a week starting with §25. Ben's savings are y = 12x. Who saves faster each week?","a": "Ben (§12 vs §10)","lvl": 2,"also": ["Ben"],"steps": ["Ana saves §10 a week. The §25 is just her start.","Ben's rate is the number in front of x. Compare the two rates."]},{"id": "8.16-01","std": "8.16","q": "A pool has 500 gallons and drains 20 gallons a minute. Write a function for the gallons left.","a": "y = 500 − 20x","lvl": 1,"also": ["y = −20x + 500"],"steps": ["Start: 500 gallons. Rate: −20 gallons each minute.","Write it as y = start + rate × x."]},{"id": "8.16-02","std": "8.16","q": "Write the function for the line through (0, 3) and (2, 11).","a": "y = 4x + 3","lvl": 2,"steps": ["The y-intercept is 3, from the point (0, 3).","Slope = {11 − 3/2 − 0}. Then write y = mx + b."]},{"id": "8.16-03","std": "8.16","q": "Write the function for the line through (1, 5) and (3, 9).","a": "y = 2x + 3","lvl": 2,"steps": ["Slope = {9 − 5/3 − 1}.","Put the slope and (1, 5) into y = mx + b to find b: 5 = m(1) + b.","Write y = mx + b."]},{"id": "8.16-04","std": "8.16","q": "A table shows x: 0, 1, 2 and y: 7, 4, 1. Write the function.","a": "y = −3x + 7","lvl": 2,"steps": ["The y-intercept is the y-value at x = 0.","Find how y changes each time x goes up 1: 7 to 4 to 1. That's the slope.","Write y = mx + b."]},{"id": "8.16-05","std": "8.16","q": "A phone costs §40 a month plus §100 for the phone. What are the rate of change and initial value?","a": "Rate §40 per month, initial value §100","lvl": 1,"part": "a","also": ["40 and 100"],"steps": ["The rate of change is what you pay each month.","The initial value is what you pay at the start, before any months."]},{"id": "8.16-06","std": "8.16","q": "A candle is 12 in tall and burns 1.5 in per hour. Write a function for its height h after t hours.","a": "h = 12 − 1.5t","lvl": 2,"part": "a","also": ["h = −1.5t + 12"],"steps": ["Start: 12 inches. Rate: −1.5 inches each hour.","Write it as h = start + rate × t."]},{"id": "8.16-07","std": "8.16","q": "A line goes through (2, 10) and (5, 19). What is the rate of change?","a": "3","lvl": 2,"part": "a","steps": ["Rate of change = change in y ÷ change in x: {19 − 10/5 − 2}.","Subtract the tops and the bottoms, then divide."]},{"id": "8.16-08","std": "8.16","q": "In y = −1.5t + 12 (candle height), what does −1.5 mean?","a": "The candle gets 1.5 inches shorter each hour","lvl": 2,"part": "a","steps": ["−1.5 is the rate of change: inches for each hour.","Negative means the height goes down. Say it in words."]},{"id": "8.16-09","std": "8.16","q": "Write the function for the line through (−2, 1) and (2, 9).","a": "y = 2x + 5","lvl": 3,"steps": ["Slope = {9 − 1/2 − (−2)}. Top: 8. Bottom: 4.","Put the slope and (2, 9) into y = mx + b to find b.","Write y = mx + b."]},{"id": "8.17-01","std": "8.17","q": "A graph of a car's distance from home goes up in a straight line. Is the distance increasing or decreasing? Linear or non-linear?","a": "Increasing, linear","lvl": 1,"also": ["increasing linear"],"steps": ["Going up from left to right means the value is getting bigger.","A straight line means a constant rate. Is that linear?"]},{"id": "8.17-02","std": "8.17","q": "A graph of a ball's height goes up, then curves back down. Is it linear or non-linear?","a": "Non-linear","lvl": 1,"choices": ["Linear","Non-linear"],"steps": ["A straight line is linear. A curve is not.","Does the ball's graph bend?"]},{"id": "8.17-03","std": "8.17","q": "A line on a graph of water in a tank slants down from left to right. Is the water increasing or decreasing?","a": "Decreasing","lvl": 1,"choices": ["Increasing","Decreasing"],"steps": ["Read the graph from left to right.","Slanting down means the amount is getting smaller."]},{"id": "8.17-04","std": "8.17","q": "A graph of distance is flat (horizontal) from minute 5 to minute 8. What is happening?","a": "The person stopped (the distance did not change)","lvl": 2,"also": ["stopped","not moving"],"steps": ["A flat line means y doesn't change.","If the distance doesn't change for 3 minutes, what is the person doing?"]},{"id": "8.17-05","std": "8.17","q": "A graph of a phone's battery drops quickly, then more slowly. Linear or non-linear?","a": "Non-linear","lvl": 2,"choices": ["Linear","Non-linear"],"steps": ["A linear graph changes at the same rate the whole time.","Fast, then slow: is that the same rate?"]},{"id": "8.17-06","std": "8.17","q": "Sketch description: Sam walks to school at a steady pace, waits for a friend, then runs. Which part of the graph is steepest?","a": "The running part","lvl": 3,"also": ["running"],"steps": ["Steeper means faster.","Which part is fastest: walking, waiting, or running?"]},{"id": "8.17-07","std": "8.17","q": "A graph of height of a plant over weeks rises faster and faster. Is it increasing at a constant rate?","a": "No; it is non-linear","lvl": 2,"also": ["no"],"steps": ["Constant rate means the same amount each week, a straight line.","Faster and faster means the amount grows each week. Is that a straight line?"]},{"id": "8.17-08","std": "8.17","q": "On a graph, a line goes down 3 units for every 1 unit right. Is the relationship increasing or decreasing?","a": "Decreasing","lvl": 1,"choices": ["Increasing","Decreasing"],"steps": ["Going down as you move right means y gets smaller.","Smaller y as x grows: increasing or decreasing?"]},{"id": "8.18-01","std": "8.18","q": "As hours studied go up, test scores go up. What kind of association is this?","a": "Positive","lvl": 1,"choices": ["Positive","Negative","No association"],"steps": ["Both go up together.","When both go up, the association is positive."]},{"id": "8.18-02","std": "8.18","q": "As a car's age goes up, its value goes down. What kind of association?","a": "Negative","lvl": 1,"choices": ["Positive","Negative","No association"],"steps": ["One goes up while the other goes down.","Opposite directions means a negative association."]},{"id": "8.18-03","std": "8.18","q": "Shoe size and favorite color. What kind of association?","a": "No association","lvl": 1,"choices": ["Positive","Negative","No association"],"steps": ["Does shoe size change what color someone likes?","If one doesn't affect the other, there's no association."]},{"id": "8.18-04","std": "8.18","q": "Points: (1, 2), (2, 4), (3, 5), (4, 8), (5, 9), (6, 30). Which point is an outlier?","a": "(6, 30)","lvl": 2,"steps": ["Look at the pattern: y goes up by about 2 each time.","Which point is far away from that pattern?"]},{"id": "8.18-05","std": "8.18","q": "On a scatter plot, most points form a group between x = 3 and x = 5. What is that called?","a": "A cluster","lvl": 1,"also": ["cluster","clustering"],"steps": ["When many points bunch together in one spot, that group has a name.","It starts with c, like a bunch of grapes."]},{"id": "8.18-06","std": "8.18","q": "Points: (1, 9), (2, 7), (3, 6), (4, 4), (5, 2). Positive, negative, or no association?","a": "Negative","lvl": 2,"choices": ["Positive","Negative","No association"],"steps": ["Read the y-values as x goes up: 9, 7, 6, 4, 2.","y goes down as x goes up. What kind of association is that?"]},{"id": "8.18-07","std": "8.18","q": "Points curve up like a U shape. Is the association linear or non-linear?","a": "Non-linear","lvl": 2,"choices": ["Linear","Non-linear"],"steps": ["Linear means the points follow a straight line.","A U shape bends. Is it straight?"]},{"id": "8.18-08","std": "8.18","q": "Temperature outside and hot chocolate sales. Likely positive or negative association?","a": "Negative","lvl": 2,"choices": ["Positive","Negative"],"steps": ["When it's warm outside, do people buy more or less hot chocolate?","One goes up while the other goes down. What kind of association?"]},{"id": "8.19-01","std": "8.19","q": "A good line of fit should have about how many points above and below it?","a": "About the same number above and below","lvl": 1,"also": ["the same","equal"],"steps": ["A line of fit goes through the middle of the data.","Picture the points on both sides of it. How many should be above, and how many below?"]},{"id": "8.19-02","std": "8.19","q": "Points cluster close to a line of fit. Is it a good fit?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["A good fit means the points stay close to the line.","These points are close. Is it a good fit?"]},{"id": "8.19-03","std": "8.19","q": "A line of fit passes through (0, 10) and (5, 35). What is its equation?","a": "y = 5x + 10","lvl": 2,"steps": ["The y-intercept is 10, from the point (0, 10).","Slope = {35 − 10/5 − 0}. Then write y = mx + b."]},{"id": "8.19-04","std": "8.19","q": "Points are spread far from the line in every direction. Is the line a good model?","a": "No","lvl": 1,"choices": ["Yes","No"],"steps": ["A good line of fit has points close to it.","These points are far from the line. Does it model the data well?"]},{"id": "8.19-05","std": "8.19","q": "Which line fits (1, 3), (2, 5), (3, 7), (4, 9) best? A. y = x + 2  B. y = 2x + 1  C. y = 3x","a": "B","lvl": 2,"choices": ["A","B","C"],"steps": ["Test each line with a point, like (1, 3): put x = 1 in and see if you get 3.","Then check (2, 5). The best line works for all the points."]},{"id": "8.19-06","std": "8.19","q": "Should a line of fit always go through the first and last points?","a": "No","lvl": 2,"choices": ["Yes","No"],"steps": ["A line of fit follows the whole pattern, not just two points.","What if the first or last point is an outlier?"]},{"id": "8.19-07","std": "8.19","q": "A line of fit is y = 2x + 4. A data point is (3, 13). How far above the line is it?","a": "3 units","lvl": 3,"also": ["3"],"steps": ["Find the line's y at x = 3: y = 2(3) + 4.","Compare it with the point's y, 13. Subtract to find how far above."]},{"id": "8.19-08","std": "8.19","q": "A line of fit passes through (2, 50) and (6, 70). What is its slope?","a": "5","lvl": 2,"steps": ["Slope = change in y ÷ change in x: {70 − 50/6 − 2}.","Subtract the tops and the bottoms, then divide."]},{"id": "8.20-01","std": "8.20","q": "A model is y = 3x + 20, where y is plant height in cm after x weeks. Predict the height after 10 weeks.","a": "50 cm","lvl": 1,"also": ["50"],"steps": ["Put x = 10 into the model: y = 3(10) + 20.","Multiply, then add."]},{"id": "8.20-02","std": "8.20","q": "In y = 3x + 20 (plant height), what does 3 mean?","a": "The plant grows 3 cm each week","lvl": 1,"part": "a","also": ["3 cm per week"],"steps": ["3 is the slope: how much y changes each time x goes up 1.","Say it with the units: centimeters each week."]},{"id": "8.20-03","std": "8.20","q": "In y = 3x + 20 (plant height), what does 20 mean?","a": "The plant was 20 cm tall at week 0","lvl": 1,"part": "a","also": ["starting height"],"steps": ["20 is the y-intercept: the value of y when x = 0.","x = 0 is week 0. Say what that means for the plant."]},{"id": "8.20-04","std": "8.20","q": "A model for ticket sales is y = 150x + 400 after x days. Predict sales on day 6.","a": "1,300","lvl": 2,"also": ["1300"],"steps": ["Put x = 6 into the model: y = 150(6) + 400.","Multiply, then add."]},{"id": "8.20-05","std": "8.20","q": "A model is y = −2.5x + 90, where y is test score and x is hours of TV a day. Predict the score for 4 hours.","a": "80","lvl": 2,"steps": ["Put x = 4 into the model: y = −2.5(4) + 90.","Multiply, then add."]},{"id": "8.20-06","std": "8.20","q": "Using y = −2.5x + 90 (score vs TV hours), what does −2.5 mean?","a": "The score drops 2.5 points for each extra hour of TV","lvl": 2,"part": "a","steps": ["−2.5 is the slope: the change in score for each extra hour of TV.","Negative means the score goes down. Say it in words."]},{"id": "8.20-07","std": "8.20","q": "Using y = 3x + 20 (plant height), when will the plant be 65 cm?","a": "Week 15","lvl": 3,"also": ["15"],"steps": ["Set the model equal to 65: 3x + 20 = 65.","Subtract 20 on both sides, then divide by 3."]},{"id": "8.20-08","std": "8.20","q": "A model is y = 12x + 30 for savings after x weeks. How much is saved after 8 weeks?","a": "§126","lvl": 1,"also": ["126"],"steps": ["Put x = 8 into the model: y = 12(8) + 30.","Multiply, then add."]},{"id": "8.21-01","std": "8.21","q": "Of 50 students: 18 boys play sports, 7 boys do not; 15 girls play sports, 10 girls do not. How many students play sports?","a": "33","lvl": 1,"steps": ["Students who play sports: boys who play plus girls who play.","Add: 18 + 15."]},{"id": "8.21-02","std": "8.21","q": "Of 50 students: 18 boys play sports, 7 boys do not; 15 girls play sports, 10 girls do not. How many girls are there?","a": "25","lvl": 1,"steps": ["Girls are the ones who play plus the ones who don't.","Add: 15 + 10."]},{"id": "8.21-03","std": "8.21","q": "Of 50 students: 18 boys play sports, 7 boys do not; 15 girls play sports, 10 girls do not. What fraction of the boys play sports?","a": "{18/25}","lvl": 2,"also": ["0.72","72%"],"steps": ["Find the number of boys: 18 + 7.","Fraction of boys who play = boys who play ÷ all boys."]},{"id": "8.21-04","std": "8.21","q": "Of 50 students: 18 boys play sports, 7 boys do not; 15 girls play sports, 10 girls do not. What percent of the girls play sports?","a": "60%","lvl": 2,"also": ["60"],"steps": ["Find the number of girls: 15 + 10.","Girls who play ÷ all girls, then change it to a percent."]},{"id": "8.21-05","std": "8.21","q": "Of 50 students: 18 boys play sports, 7 boys do not; 15 girls play sports, 10 girls do not. Is there an association between being a boy and playing sports?","a": "Yes, a weak one (72% of boys vs 60% of girls)","lvl": 3,"also": ["yes"],"steps": ["Boys who play: 18 out of 25. Change it to a percent.","Girls who play: 15 out of 25. Change it to a percent.","If the percents are different, there's an association. Is the gap big or small?"]},{"id": "8.21-06","std": "8.21","q": "Of 50 students: 18 boys play sports, 7 boys do not; 15 girls play sports, 10 girls do not. What percent of all students do not play sports?","a": "34%","lvl": 2,"also": ["34"],"steps": ["Students who don't play: 7 + 10.","Divide by all 50 students, then change it to a percent."]},{"id": "8.21-07","std": "8.21","q": "Of 50 students: 18 boys play sports, 7 boys do not; 15 girls play sports, 10 girls do not. Of the students who play sports, what fraction are girls?","a": "{5/11}","lvl": 3,"steps": ["Students who play sports: 18 + 15.","Girls who play ÷ all who play. Simplify the fraction."]},{"id": "8.21-08","std": "8.21","q": "In a two-way table, a row relative frequency compares a cell to its ___.","a": "Row total","lvl": 1,"choices": ["Row total","Column total","Grand total"],"steps": ["A row relative frequency looks across one row of the table.","You divide each cell by the total for that row. What is that total called?"]},{"id": "8.22-01","std": "8.22","q": "A segment is 5 cm long. After a rotation, how long is it?","a": "5 cm","lvl": 1,"also": ["5"],"steps": ["A rotation turns a figure. It doesn't stretch or shrink it.","So does the length change?"]},{"id": "8.22-02","std": "8.22","q": "An angle is 72°. After a reflection, what is its measure?","a": "72°","lvl": 1,"also": ["72"],"steps": ["A reflection flips a figure. It doesn't change angles.","So does the angle change?"]},{"id": "8.22-03","std": "8.22","q": "Two parallel lines are translated. Are the images parallel?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["A translation slides every point the same way.","Lines that never meet, slid the same way, still never meet. So are they still parallel?"]},{"id": "8.22-04","std": "8.22","q": "Do rigid motions change size or shape?","a": "No","lvl": 1,"choices": ["Yes","No"],"steps": ["Rigid motions are slides, flips and turns.","Does sliding, flipping or turning a shape change its size or shape?"]},{"id": "8.22-05","std": "8.22","q": "Triangle ABC is reflected and then translated to triangle DEF. Are the triangles congruent?","a": "Yes","lvl": 1,"part": "a","choices": ["Yes","No"],"steps": ["Reflections and translations are rigid motions. They keep size and shape.","Same size and same shape means congruent."]},{"id": "8.22-06","std": "8.22","q": "Which is NOT a rigid motion? A. Rotation  B. Reflection  C. Dilation  D. Translation","a": "C","lvl": 2,"choices": ["A","B","C","D"],"steps": ["Rigid motions keep the same size.","Which choice makes a figure bigger or smaller?"]},{"id": "8.22-07","std": "8.22","q": "Square A has sides 4. Square B has sides 6. Can rigid motions map A onto B?","a": "No (they are different sizes)","lvl": 2,"part": "a","also": ["no"],"steps": ["Rigid motions keep the same size.","Sides of 4 and sides of 6 are different sizes. Can a slide, flip or turn change that?"]},{"id": "8.22-08","std": "8.22","q": "Triangle P is at (1, 1), (3, 1), (1, 4). Triangle Q is at (4, 3), (6, 3), (4, 6). Describe a rigid motion that maps P onto Q.","a": "Translate 3 right and 2 up","lvl": 3,"part": "a","also": ["(x + 3, y + 2)"],"steps": ["Match a pair of corners: (1, 1) goes to (4, 3).","How far right did it move: 4 − 1? How far up: 3 − 1?","Check another corner with the same move."]},{"id": "8.23-01","std": "8.23","q": "Translate (2, −3) 4 units left and 5 units up.","a": "(−2, 2)","lvl": 1,"steps": ["Left changes x: subtract 4 from x. Up changes y: add 5 to y.","x: 2 − 4. y: −3 + 5."]},{"id": "8.23-02","std": "8.23","q": "Reflect (3, 7) over the x-axis.","a": "(3, −7)","lvl": 1,"steps": ["Reflecting over the x-axis keeps x and changes the sign of y.","(x, y) becomes (x, −y)."]},{"id": "8.23-03","std": "8.23","q": "Reflect (−4, 2) over the y-axis.","a": "(4, 2)","lvl": 1,"steps": ["Reflecting over the y-axis keeps y and changes the sign of x.","(x, y) becomes (−x, y)."]},{"id": "8.23-04","std": "8.23","q": "Rotate (2, 5) 90° counterclockwise about the origin.","a": "(−5, 2)","lvl": 2,"steps": ["Rule for 90° counterclockwise: (x, y) becomes (−y, x).","Here x = 2 and y = 5. Put them into the rule."]},{"id": "8.23-05","std": "8.23","q": "Rotate (3, −1) 180° about the origin.","a": "(−3, 1)","lvl": 2,"steps": ["Rule for 180°: (x, y) becomes (−x, −y).","Change the sign of both numbers."]},{"id": "8.23-06","std": "8.23","q": "Dilate (4, −6) by a scale factor of {1/2} centered at the origin.","a": "(2, −3)","lvl": 2,"steps": ["A dilation multiplies both coordinates by the scale factor.","Multiply: {1/2} × 4 and {1/2} × (−6)."]},{"id": "8.23-07","std": "8.23","q": "Dilate (−3, 2) by a scale factor of 3 centered at the origin.","a": "(−9, 6)","lvl": 1,"steps": ["A dilation multiplies both coordinates by the scale factor.","Multiply: 3 × (−3) and 3 × 2."]},{"id": "8.23-08","std": "8.23","q": "Rotate (−1, 4) 90° clockwise about the origin.","a": "(4, 1)","lvl": 3,"steps": ["Rule for 90° clockwise: (x, y) becomes (y, −x).","Here x = −1 and y = 4. Put them into the rule."]},{"id": "8.23-09","std": "8.23","q": "What rule describes a translation 6 left and 2 down?","a": "(x − 6, y − 2)","lvl": 2,"steps": ["Left changes x by subtracting. Down changes y by subtracting.","Write it as (x − left, y − down)."]},{"id": "8.23-10","std": "8.23","q": "A point (x, y) becomes (y, −x). What transformation is this?","a": "A 90° clockwise rotation about the origin","lvl": 3,"also": ["90° clockwise rotation","rotation 90 clockwise"],"steps": ["Try a point: (1, 0) becomes (0, −1).","(1, 0) is on the right. (0, −1) is below. Which way did it turn, and how far?"]},{"id": "8.24-01","std": "8.24","q": "Triangle A has sides 3, 4, 5. Triangle B has sides 6, 8, 10. Are they similar? What is the scale factor from A to B?","a": "Yes, scale factor 2","lvl": 1,"also": ["2","yes"],"steps": ["Divide matching sides: 6 ÷ 3, 8 ÷ 4, 10 ÷ 5.","If every ratio is the same, the triangles are similar, and that ratio is the scale factor."]},{"id": "8.24-02","std": "8.24","q": "A rectangle 2 by 5 is dilated by a factor of 3. What are the new dimensions?","a": "6 by 15","lvl": 1,"steps": ["A dilation multiplies every side by the scale factor.","Multiply each side by 3: 2 × 3 and 5 × 3."]},{"id": "8.24-03","std": "8.24","q": "Are congruent figures also similar?","a": "Yes (scale factor 1)","lvl": 2,"choices": ["Yes (scale factor 1)","No"],"steps": ["Similar means same shape. Congruent means same shape and same size.","Same size is a scale factor of 1. Is that still the same shape?"]},{"id": "8.24-04","std": "8.24","q": "A figure is dilated by {1/2}, then rotated 90°. Is the image similar to the original?","a": "Yes","lvl": 1,"choices": ["Yes","No"],"steps": ["A dilation changes the size but keeps the shape.","A rotation keeps the size and the shape. Is the shape still the same?"]},{"id": "8.24-05","std": "8.24","q": "Rectangle 4 by 6 and rectangle 6 by 8. Are they similar?","a": "No (4/6 is not equal to 6/8)","lvl": 2,"also": ["no"],"steps": ["Compare short sides: 4 and 6. Compare long sides: 6 and 8.","Write each as a fraction: {4/6} and {6/8}. Simplify. Are they equal?"]},{"id": "8.24-06","std": "8.24","q": "Triangle (0, 0), (2, 0), (0, 4) maps to (0, 0), (6, 0), (0, 12). Describe the transformation.","a": "A dilation by a scale factor of 3 centered at the origin","lvl": 2,"also": ["dilation by 3","scale factor 3"],"steps": ["Compare matching points: (2, 0) goes to (6, 0), and (0, 4) goes to (0, 12).","Each coordinate was multiplied by the same number. What number? That's a dilation."]},{"id": "8.24-07","std": "8.24","q": "Two triangles have angles 40°, 60°, 80° and 40°, 60°, 80°. Are they similar?","a": "Yes","lvl": 2,"choices": ["Yes","No"],"steps": ["Similar triangles have all the same angles.","Compare the angles. Do they all match?"]},{"id": "8.24-08","std": "8.24","q": "Similar triangles: one has sides 5, 7, 9 and the other's shortest side is 15. Find its longest side.","a": "27","lvl": 3,"steps": ["Find the scale factor from the shortest sides: 15 ÷ 5.","Multiply the longest side, 9, by the scale factor."]},{"id": "8.25-01","std": "8.25","q": "Two parallel lines are cut by a transversal. One angle is 65°. Find its corresponding angle.","a": "65°","lvl": 1,"also": ["65"],"steps": ["Corresponding angles are in the same spot at each crossing.","When the lines are parallel, corresponding angles are equal."]},{"id": "8.25-02","std": "8.25","q": "Two parallel lines are cut by a transversal. One angle is 110°. Find its alternate interior angle.","a": "110°","lvl": 1,"also": ["110"],"steps": ["Alternate interior angles are between the parallel lines, on opposite sides of the transversal.","When the lines are parallel, alternate interior angles are equal."]},{"id": "8.25-03","std": "8.25","q": "Two parallel lines are cut by a transversal. Same-side interior angles are (3x)° and (2x + 30)°. Find x.","a": "x = 30","lvl": 3,"steps": ["Same-side interior angles add up to 180°: 3x + 2x + 30 = 180.","Combine like terms: 5x + 30 = 180.","Subtract 30 on both sides, then divide by 5."]},{"id": "8.25-04","std": "8.25","q": "Alternate exterior angles are (4x − 10)° and (2x + 40)°. Find x.","a": "x = 25","lvl": 2,"steps": ["Alternate exterior angles are equal: 4x − 10 = 2x + 40.","Subtract 2x on both sides, then add 10. Now it's 2x = 50.","Divide both sides by 2."]},{"id": "8.25-05","std": "8.25","q": "Corresponding angles are (5x + 5)° and 80°. Find x.","a": "x = 15","lvl": 2,"steps": ["Corresponding angles are equal: 5x + 5 = 80.","Subtract 5 on both sides, then divide by 5."]},{"id": "8.25-06","std": "8.25","q": "Two angles of a triangle are 48° and 67°. Find the third angle.","a": "65°","lvl": 1,"part": "a","also": ["65"],"steps": ["The three angles of a triangle add up to 180°.","Add the two angles you know: 48 + 67.","Subtract that from 180."]},{"id": "8.25-07","std": "8.25","q": "The angles of a triangle are (x + 3)°, (3x + 2)° and (2x + 1)°. Find x.","a": "x = 29","lvl": 2,"part": "a","steps": ["Add the angles and set them equal to 180: (x + 3) + (3x + 2) + (2x + 1) = 180.","Combine like terms: 6x + 6 = 180.","Subtract 6 on both sides, then divide by 6."]},{"id": "8.25-08","std": "8.25","q": "An isosceles triangle has a vertex angle of 40°. Find each base angle.","a": "70°","lvl": 2,"part": "a","also": ["70"],"steps": ["Take away the vertex angle: 180 − 40.","The two base angles are equal, so split what's left in half."]},{"id": "8.25-09","std": "8.25","q": "The angles of a triangle are in the ratio 2 : 3 : 4. Find the largest angle.","a": "80°","lvl": 3,"part": "a","also": ["80"],"steps": ["Write the angles as 2x, 3x and 4x. They add up to 180: 9x = 180.","Solve for x.","The largest angle is 4x."]},{"id": "8.25-10","std": "8.25","q": "An exterior angle of a triangle is 120°. One remote interior angle is 50°. Find the other.","a": "70°","lvl": 3,"part": "a","also": ["70"],"steps": ["An exterior angle equals the two remote interior angles added together.","So the missing angle is 120 minus the one you know."]},{"id": "8.26-01","std": "8.26","q": "Write the Pythagorean Theorem.","a": "a² + b² = c²","lvl": 1,"steps": ["It connects the three sides of a right triangle. The legs are a and b. The hypotenuse is c.","Square each leg and add them. That equals the hypotenuse squared."]},{"id": "8.26-02","std": "8.26","q": "In a right triangle, what is the hypotenuse?","a": "The side across from the right angle (the longest side)","lvl": 1,"also": ["longest side"],"steps": ["Find the right angle in the triangle.","The side across from it has a special name, and it's always the longest side."]},{"id": "8.26-03","std": "8.26","q": "Is a triangle with sides 5, 12, 13 a right triangle?","a": "Yes (25 + 144 = 169)","lvl": 1,"also": ["yes"],"steps": ["Square the two short sides: 5² and 12². Add them.","Square the longest side: 13². If the two answers match, it's a right triangle."]},{"id": "8.26-04","std": "8.26","q": "Is a triangle with sides 6, 7, 9 a right triangle?","a": "No (36 + 49 = 85, not 81)","lvl": 2,"also": ["no"],"steps": ["Square the two short sides: 6² and 7². Add them.","Square the longest side: 9². Do the two answers match?"]},{"id": "8.26-05","std": "8.26","q": "Is a triangle with sides 8, 15, 17 a right triangle?","a": "Yes (64 + 225 = 289)","lvl": 2,"also": ["yes"],"steps": ["Square the two short sides: 8² and 15². Add them.","Square the longest side: 17². Do the two answers match?"]},{"id": "8.26-06","std": "8.26","q": "Squares are drawn on the sides of a right triangle. The two small squares have areas 9 and 16. What is the area of the big square?","a": "25","lvl": 2,"steps": ["The squares' areas are a², b² and c².","a² + b² = c², so add the two small areas."]},{"id": "8.26-07","std": "8.26","q": "Is a triangle with sides 1.5, 2 and 2.5 a right triangle?","a": "Yes (2.25 + 4 = 6.25)","lvl": 3,"also": ["yes"],"steps": ["Square the two short sides: 1.5² and 2². Add them.","Square the longest side: 2.5². Do the two answers match?"]},{"id": "8.26-08","std": "8.26","q": "Which side goes in c when you check sides 9, 40, 41?","a": "41 (the longest side)","lvl": 1,"also": ["41"],"steps": ["c is always the hypotenuse.","The hypotenuse is the longest side. Which number is biggest?"]},{"id": "8.27-01","std": "8.27","q": "Find the distance between (1, 2) and (4, 6).","a": "5","lvl": 1,"steps": ["Make a right triangle. Across: 4 − 1. Up: 6 − 2.","Use a² + b² = c² with those two legs.","Take the square root of the sum."]},{"id": "8.27-02","std": "8.27","q": "Find the distance between (−2, −1) and (4, 7).","a": "10","lvl": 2,"steps": ["Across: 4 − (−2). Up: 7 − (−1).","Use a² + b² = c² with those two legs.","Take the square root of the sum."]},{"id": "8.27-03","std": "8.27","q": "Find the distance between (0, 0) and (5, 12).","a": "13","lvl": 1,"steps": ["Across: 5 − 0. Up: 12 − 0.","Use a² + b² = c²: 5² + 12².","Take the square root of the sum."]},{"id": "8.27-04","std": "8.27","q": "Find the distance between (−3, 4) and (3, −4).","a": "10","lvl": 2,"steps": ["Across: 3 − (−3). Down: 4 − (−4).","Use a² + b² = c² with those two legs.","Take the square root of the sum."]},{"id": "8.27-05","std": "8.27","q": "Find the distance between (1, 1) and (4, 3). Round to the nearest tenth.","a": "3.6","lvl": 2,"also": ["√13"],"steps": ["Across: 4 − 1. Up: 3 − 1.","Use a² + b² = c²: 3² + 2².","Take the square root and round to the nearest tenth."]},{"id": "8.27-06","std": "8.27","q": "Find the distance between (−2, 3) and (2, −1). Round to the nearest tenth.","a": "5.7","lvl": 3,"also": ["√32","4√2"],"steps": ["Across: 2 − (−2). Down: 3 − (−1).","Use a² + b² = c²: 4² + 4².","Take the square root and round to the nearest tenth."]},{"id": "8.27-07","std": "8.27","q": "Points A(2, 1) and B(2, 9) are on a vertical line. How far apart are they?","a": "8","lvl": 1,"steps": ["Both points have x = 2, so only y changes.","Distance = 9 − 1."]},{"id": "8.27-08","std": "8.27","q": "On a map grid, school is at (0, 0) and the park is at (6, 8). Each unit is 1 block. How far is the park in a straight line?","a": "10 blocks","lvl": 2,"also": ["10"],"steps": ["Across: 6 blocks. Up: 8 blocks. Those are the legs.","Use a² + b² = c²: 6² + 8².","Take the square root of the sum."]},{"id": "8.28-01","std": "8.28","q": "The legs of a right triangle are 6 and 8. Find the hypotenuse.","a": "10","lvl": 1,"steps": ["Use a² + b² = c². The legs are 6 and 8.","Square them and add: 36 + 64.","Take the square root of the sum."]},{"id": "8.28-02","std": "8.28","q": "A right triangle has a hypotenuse of 13 and a leg of 5. Find the other leg.","a": "12","lvl": 1,"steps": ["Use a² + b² = c². The hypotenuse is the longest side, so c = 13.","Put in what you know: 5² + b² = 13², so 25 + b² = 169.","Subtract 25, then take the square root."]},{"id": "8.28-03","std": "8.28","q": "The legs are 7 and 24. Find the hypotenuse.","a": "25","lvl": 2,"steps": ["Use a² + b² = c². The legs are 7 and 24.","Square them and add: 49 + 576.","Take the square root of the sum."]},{"id": "8.28-04","std": "8.28","q": "A 10-foot ladder leans against a wall. Its base is 6 feet from the wall. How high does it reach?","a": "8 feet","lvl": 2,"also": ["8"],"steps": ["The ladder is the hypotenuse: c = 10. The ground distance is a leg: 6.","6² + h² = 10², so 36 + h² = 100.","Subtract 36, then take the square root."]},{"id": "8.28-05","std": "8.28","q": "A TV screen is 32 in wide and 18 in tall. Find the diagonal to the nearest inch.","a": "37 in","lvl": 3,"also": ["37"],"steps": ["The width and height are the legs. The diagonal is the hypotenuse.","32² + 18² = 1024 + 324.","Take the square root and round to the nearest inch."]},{"id": "8.28-06","std": "8.28","q": "The legs of a right triangle are 4 and 5. Find the hypotenuse to the nearest tenth.","a": "6.4","lvl": 2,"also": ["√41"],"steps": ["Use a² + b² = c². The legs are 4 and 5.","Square them and add: 16 + 25.","Take the square root and round to the nearest tenth."]},{"id": "8.28-07","std": "8.28","q": "A soccer field is 100 yd by 60 yd. How long is the diagonal to the nearest yard?","a": "117 yd","lvl": 3,"also": ["117"],"steps": ["The length and width are the legs. The diagonal is the hypotenuse.","100² + 60² = 10,000 + 3,600.","Take the square root and round to the nearest yard."]},{"id": "8.28-08","std": "8.28","q": "A square has a diagonal of 10 cm. Find the side length to the nearest tenth.","a": "7.1 cm","lvl": 3,"also": ["7.1","√50","5√2"],"steps": ["A square's diagonal makes a right triangle with two equal legs, s and s.","s² + s² = 10², so 2s² = 100. Divide by 2.","Take the square root and round to the nearest tenth."]},{"id": "8.28-09","std": "8.28","q": "You walk 9 blocks north and 12 blocks east. How far are you from where you started in a straight line?","a": "15 blocks","lvl": 2,"also": ["15"],"steps": ["North and east make a right angle. The legs are 9 and 12.","Square them and add: 81 + 144.","Take the square root of the sum."]},{"id": "8.29-01","std": "8.29","q": "A cone and a cylinder have the same radius and height. How many cones of water fill the cylinder?","a": "3","lvl": 1,"steps": ["A cone's volume is {1/3} of a cylinder's with the same radius and height.","If one cone fills {1/3} of the cylinder, how many cones fill all of it?"]},{"id": "8.29-02","std": "8.29","q": "A cone has the same radius and height as a cylinder with volume 90 cm³. What is the cone's volume?","a": "30 cm³","lvl": 1,"also": ["30"],"steps": ["A cone holds {1/3} of a cylinder with the same radius and height.","Find {1/3} of 90."]},{"id": "8.29-03","std": "8.29","q": "A sphere fits exactly inside a cylinder (same radius, height = diameter). What fraction of the cylinder's volume is the sphere?","a": "{2/3}","lvl": 2,"steps": ["Cylinder with height 2r: V = πr² × 2r = 2πr³. Sphere: V = {4/3}πr³.","Divide the sphere by the cylinder: {4/3}πr³ ÷ 2πr³. The πr³ cancels.","Find {4/3} ÷ 2."]},{"id": "8.29-04","std": "8.29","q": "A cylinder with radius r and height 2r has volume 2πr³. What is the volume of a sphere with radius r?","a": "{4/3}πr³","lvl": 2,"steps": ["A sphere that fits inside this cylinder holds {2/3} of it.","Find {2/3} × 2πr³."]},{"id": "8.29-05","std": "8.29","q": "A cylinder holds 600 mL. A cone with the same radius and height is filled and poured in. How many times can you pour before the cylinder is full?","a": "3","lvl": 1,"steps": ["A cone holds {1/3} of a cylinder with the same radius and height.","How many thirds make one whole?"]},{"id": "8.29-06","std": "8.29","q": "A cylinder (height = diameter) holds 150 cm³. What is the volume of the sphere that fits inside?","a": "100 cm³","lvl": 3,"also": ["100"],"steps": ["The sphere that fits inside holds {2/3} of the cylinder.","Find {2/3} × 150."]},{"id": "8.29-07","std": "8.29","q": "Why is a cone's volume {1/3} of a cylinder's with the same base and height?","a": "Three cones of water fill the cylinder exactly","lvl": 2,"steps": ["Think about filling a cylinder with water from a cone with the same base and height.","How many cones does it take? That's why the fraction is {1/3}."]},{"id": "8.29-08","std": "8.29","q": "Write the formula for the volume of a cone.","a": "V = {1/3}πr²h","lvl": 1,"also": ["1/3πr²h"],"steps": ["A cylinder is V = πr²h.","A cone holds {1/3} of a cylinder with the same base and height. Put {1/3} in front."]},{"id": "8.30-01","std": "8.30","q": "Find the volume of a cylinder with radius 3 cm and height 10 cm. Use 3.14.","a": "282.6 cm³","lvl": 1,"also": ["282.6"],"steps": ["Cylinder: V = πr²h.","Square the radius: 3² = 9. Then multiply 3.14 × 9 × 10."]},{"id": "8.30-02","std": "8.30","q": "Find the volume of a cylinder with radius 4 in and height 5 in. Leave it in terms of π.","a": "80π in³","lvl": 1,"also": ["80π"],"steps": ["Cylinder: V = πr²h.","Square the radius: 4² = 16. Multiply by the height, 5, and keep π."]},{"id": "8.30-03","std": "8.30","q": "Find the volume of a cone with radius 3 ft and height 4 ft. Leave it in terms of π.","a": "12π ft³","lvl": 2,"also": ["12π"],"steps": ["Cone: V = {1/3}πr²h.","Square the radius: 3² = 9. Multiply 9 × 4, take {1/3} of it, and keep π."]},{"id": "8.30-04","std": "8.30","q": "Find the volume of a sphere with radius 3 m. Leave it in terms of π.","a": "36π m³","lvl": 2,"also": ["36π"],"steps": ["Sphere: V = {4/3}πr³.","Cube the radius: 3³ = 27. Multiply by {4/3} and keep π."]},{"id": "8.30-05","std": "8.30","q": "Find the volume of a cone with diameter 10 cm and height 9 cm. Use 3.14.","a": "235.5 cm³","lvl": 2,"also": ["235.5"],"steps": ["The radius is half the diameter: 10 ÷ 2 = 5.","Cone: V = {1/3}πr²h = {1/3} × 3.14 × 25 × 9.","Do 25 × 9, take {1/3}, then multiply by 3.14."]},{"id": "8.30-06","std": "8.30","q": "Find the volume of a sphere with diameter 6 in. Use 3.14 and round to the nearest tenth.","a": "113.0 in³","lvl": 2,"also": ["113.0"],"steps": ["The radius is half the diameter: 6 ÷ 2 = 3.","Sphere: V = {4/3}πr³ = {4/3} × 3.14 × 27.","Do {4/3} × 27 first, then multiply by 3.14. Round to the nearest tenth."]},{"id": "8.30-07","std": "8.30","q": "A can is 12 cm tall with a radius of 4 cm. How much does it hold? Use 3.14.","a": "602.88 cm³","lvl": 2,"also": ["602.88"],"steps": ["A can is a cylinder: V = πr²h.","Square the radius: 4² = 16. Then multiply 3.14 × 16 × 12."]},{"id": "8.30-08","std": "8.30","q": "A cylinder has volume 72π and radius 3. Find its height.","a": "8","lvl": 3,"steps": ["Cylinder: V = πr²h, so 72π = π × 3² × h.","3² = 9, so 72π = 9πh.","Divide both sides by 9π."]},{"id": "8.30-09","std": "8.30","q": "A cone-shaped cup has radius 2 in and height 6 in. A cylinder cup has radius 2 in and height 6 in. How many cone cups fill the cylinder cup?","a": "3","lvl": 1,"steps": ["Same radius and same height: a cone holds {1/3} of the cylinder.","How many thirds make one whole cylinder?"]},{"id": "8.30-10","std": "8.30","q": "An ice cream cone (radius 1 in, height 5 in) has a half sphere of ice cream (radius 1 in) on top. Find the total volume in terms of π.","a": "{7/3}π in³","lvl": 3,"also": ["7/3π","2{1/3}π"],"steps": ["Cone: V = {1/3}π(1²)(5) = {5/3}π.","Half sphere: V = {1/2} × {4/3}π(1³) = {2/3}π.","Add the two parts. Keep π."]}]};
